interactions.prompt:
You MUST make sure that the hooks return exactly this information (additionally make sure to add raw as a field where you add the raw input json and leave it for logging for now):

Events
``yaml
git:
  commit:
    starting: # pre-commit
      message: {{COMMITMESSAGE}} 
    ended: # post-commit
      sha: {{COMMITSHA}}
      message: {{COMMITMESSAGE}}
agent:
  starting:
    session: {{ID}}
    timestamp: {{TIMESTAMP}}
    client: {{CLIENT}}
    parent: {{PARENT}}
  ended:
    session: {{ID}}
    timestamp: {{TIMESTAMP}}
    client: {{CLIENT}}
  prompt:
    submitting:
      session: {{ID}}
      timestamp: {{TIMESTAMP}}
      client: {{CLIENT}}
      prompt: {{PROMPT}}
  compacting:
    session: {{ID}}
    timestamp: {{TIMESTAMP}}
    client: {{CLIENT}}
    chat: {{CHAT}}
  tool:
    starting: # all tools but excluding task, code, terminal
      session: {{ID}}
      timestamp: {{TIMESTAMP}}
      client: {{CLIENT}}
      name: {{NAME}} # name of the tool
      input: {{INPUT}}
    ended: # excluding task, code and terminal
      session: {{ID}}
      timestamp: {{TIMESTAMP}}
      client: {{CLIENT}}
      name: {{NAME}} # name of the tool
      input: {{INPUT}}
      response: {{RESPONSE}}
    plan: # A list of tasks - usually TODO lists in the native clients
      updating: # Planning involves changing the task list
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        steps:
          - name: {{STEPNAME}}
          - status: {{STATUS}} # completed, in progress, pending
    code:
      searching: # All searches such as file read, grep,
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        query: {{QUERY}} # regex, glob, file path, etc
        include: [{{INCLUDEPATTERN}}] # file glob patterns, line numbers, etc
        exclude: [{{EXCLUDEPATTERN}}]
      editing:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        path: {{FILEPATH}}
        old: {{OLDSTRING}}
        new: {{NEWSTRING}}
        all: {{REPLACEALLSTRINGS}} # false: just first, true: replace all occurrences
      edited:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        path: {{FILEPATH}}
        old: {{OLDSTRING}}
        new: {{NEWSTRING}}
    terminal:
      starting:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        command: {{COMMAND}}
      ended:
        session: {{ID}}
        timestamp: {{TIMESTAMP}}
        client: {{CLIENT}}
        command: {{COMMAND}}
        pid: {{PID}} # process id, execution id, etc
        terminated: {{HASTERMINATED}} # true: stopped, false: still running
        stdout: {{STDOUT}}
        stderr: {{STDERR}}
``
